import cv2

# Paste the RTSP URL generated by the test service
url = "rtsp://rtsp.rtsplink.com/live/test?token=7cd512bbefb5c01805921437b75ad0541038ea48e6d367a91dbc18be55f91aed"

cap = cv2.VideoCapture(url, cv2.CAP_FFMPEG)

if not cap.isOpened():
    print("Connection failed")
else:
    print("Connected successfully!")

    for _ in range(100):
        ret, frame = cap.read()

        if not ret:
            print("Could not read frame")
            break

        print("Frame shape:", frame.shape)

    cap.release()